/**
 * The v2 scorecard preview's stylesheet, same constraints as the v1 one:
 * a TypeScript string (the renderer stays synchronous), zero network, and
 * values derived from locked sources rather than invented.
 *
 * Since plan 039 (2026-09-11) the values come from the public site's
 * design language (operator direction pick: fixed dark scheme matching
 * the report), transcribed by hand - never imported from packages/site:
 *
 * - packages/site/app/globals.css's dark scheme, through the report's own
 *   token transcription (bg/surface/text ladder, sky accent, hairline,
 *   raised cards), as recorded in docs/report/report-design-tokens.md and
 *   the flat sources in docs/report/design/
 * - packages/report/src/styles/nocturne.css (the same tokens as applied
 *   to the report, spacing rhythm, radius ladder)
 * - packages/report/src/template/design-tokens.ts (the severity tile
 *   pairs, the report-design doc's source of truth for badges)
 * - packages/report/src/styles/paged.css's print block (the light print
 *   ground #f7f7f5 and its measured print-safe text colors)
 * - the site's dossier motif (DESIGN.md, "The Dossier Rule Set") for the
 *   three proof cards: raised card with the finding-red mark above the
 *   title, decoration only, never a severity
 * - Avenir Next, the site's licensed face (400/600/700), inlined as
 *   base64 data URIs to keep the document zero-network;
 *   font-display: block
 *
 * The print block is what the operator PDF prints through: the dark screen
 * ground inverts to the report's print ground so a downloaded PDF is not a
 * wall of ink, and the severity tiles swap to the same print-safe pairs the
 * paid report uses for text on that light background.
 */

export const OUTREACH_PREVIEW_STYLES_V2 = `
:root {
  color-scheme: dark;
  /* The site's dark scheme, through the report's token transcription
     (globals.css dark block; see the header comment). One fixed scheme:
     the preview matches the PDF and does not follow the visitor's OS
     preference (operator pick, plan 039). */
  --bg: #0e141c;
  --surface: #16202c;
  --text: #e9eef5;
  --muted: #b6c1ce;
  --faint: #909cab;
  --accent: #38bdf8;
  --accent-strong: #7dd3fc;
  --accent-soft: rgb(56 189 248 / 0.16);
  --divider: rgba(233, 238, 245, 0.13);
  --mark-finding: #dc2626;
  /* Cover glow: the report cover's sky-navy recipe on this ground
     (nocturne.css --color-section-glow / --color-section). */
  --cover-glow: #14293e;
  --cover-ground: #0d1926;
  --radius: 12px;
  --radius-sm: 4px;
  --space-1: 2.8px;
  --space-2: 5.6px;
  --space-3: 8.4px;
  --space-4: 11.2px;
  --space-6: 16.8px;
  --space-8: 22.4px;
  --space-12: 33.6px;
  /* design-tokens.ts severity pairs: the plan 023 severity hues
     re-verified on their 0.12-alpha tile tints over the new ground
     (worst pair 5.38:1). */
  --sev-critical: #d97b82; --sev-critical-bg: #262028;
  --sev-serious: #dba36c;  --sev-serious-bg: #272526;
  --sev-moderate: #d6c96e; --sev-moderate-bg: #262a26;
  --sev-minor: #b2b6ca;    --sev-minor-bg: #222731;
}

@font-face {
  font-family: 'Avenir Next';
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url(data:font/woff2;base64,) format('woff2');
}
@font-face {
  font-family: 'Avenir Next';
  font-style: normal;
  font-weight: 600;
  font-display: block;
  src: url(data:font/woff2;base64,) format('woff2');
}
@font-face {
  font-family: 'Avenir Next';
  font-style: normal;
  font-weight: 700;
  font-display: block;
  src: url(data:font/woff2;base64,) format('woff2');
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: var(--space-12) var(--space-6);
  /* The cover glow is painted on the document canvas at its top, so it
     bleeds edge to edge without any overflow-prone negative margins; it
     has faded to the ground long before the first section card begins. */
  background-color: var(--bg);
  background-image: radial-gradient(
    ellipse 900px 560px at 50% 0%,
    var(--cover-glow) 0%,
    var(--cover-ground) 45%,
    var(--bg) 85%
  );
  background-repeat: no-repeat;
  color: var(--text);
  font-family: 'Avenir Next', ui-sans-serif, system-ui, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.65;
}

main { max-width: 720px; margin: 0 auto; }

h1, h2, h3 { font-weight: 600; }

h1 { font-size: 1.7rem; line-height: 1.2; letter-spacing: -0.02em; margin: var(--space-2) 0 var(--space-3); }
h2 { font-size: 1.15rem; margin: 0 0 var(--space-4); }
h3 { font-size: 1rem; margin: 0 0 var(--space-2); }

p { margin: 0 0 var(--space-4); }
p:last-child { margin-bottom: 0; }

a { color: var(--accent); }
a:focus-visible {
  /* WCAG 2.4.7: the browser default is easy to lose on this ground. */
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

/* The cover (operator request, plan 039 review): the document's own opening
   elements - label, business name, lede, scan date, in that order - presented
   as a full-height opening in the report cover's grammar: the sky-navy glow on
   the near-navy ground, centered type, and the symmetric-fade accent rule
   (drawn below) before the date line. Print fills exactly the first A4 page,
   so the operator PDF opens on a real cover page. */
.cover {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  min-height: calc(100svh - var(--space-12));
}

/* The hero label's string is locked content, but its treatment is not the
   banned kicker pattern (impeccable kicker-above-heading): sentence case,
   body size, muted - a quiet intro line, not a tracked uppercase label. */
.label {
  color: var(--faint);
  font-size: 0.9rem;
  margin: 0 0 var(--space-2);
}

.cover h1 {
  font-size: 2.375rem;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin: var(--space-3) 0;
}

.cover .lede {
  max-width: 34rem;
  margin-left: auto;
  margin-right: auto;
}

/* The report cover's centered symmetric-fade accent rule, drawn before the
   scan-date line. Decoration only: no content element is added. */
.cover .meta::before {
  content: '';
  display: block;
  width: 160px;
  height: 1px;
  margin: var(--space-4) auto var(--space-6);
  background: linear-gradient(to right, transparent, var(--accent), transparent);
}

.lede { color: var(--muted); }

.meta { color: var(--muted); font-size: 0.85rem; }

section:not(.disclosure) {
  background: var(--surface);
  border: 1px solid var(--divider);
  border-radius: var(--radius);
  padding: var(--space-6);
  margin: 0 0 var(--space-6);
}

/* The severity heading carries the renderer's own spacing hook; without
   this rule it renders flush under the totals tiles above it. */
.mt { margin-top: var(--space-6); }

/* Stat tiles: the report's 4-up tile rhythm, stacked on small screens. */
.tiles {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-3);
}
.tiles.four { grid-template-columns: repeat(4, 1fr); }
.tile {
  background: var(--bg);
  border: 1px solid var(--divider);
  border-radius: var(--radius-sm);
  padding: var(--space-4);
}
.tile .value {
  font-size: 1.6rem;
  font-weight: 700;
  line-height: 1.2;
}
.tile .key { color: var(--muted); font-size: 0.8rem; margin-top: var(--space-1); }

/* WCAG 1.4.10: at reflow widths the report's 3-up and 4-up tile rows
   collapse to two columns, so a long tile label can never force the page
   sideways at 320px. */
@media (max-width: 480px) {
  .tiles, .tiles.four { grid-template-columns: repeat(2, 1fr); }
}

/* Severity tiles: the pair carries the meaning, the label carries the word. */
.tile.severity-critical { background: var(--sev-critical-bg); }
.tile.severity-critical .value { color: var(--sev-critical); }
.tile.severity-serious { background: var(--sev-serious-bg); }
.tile.severity-serious .value { color: var(--sev-serious); }
.tile.severity-moderate { background: var(--sev-moderate-bg); }
.tile.severity-moderate .value { color: var(--sev-moderate); }
.tile.severity-minor { background: var(--sev-minor-bg); }
.tile.severity-minor .value { color: var(--sev-minor); }

/* The three proof cards wear the site's dossier motif (DESIGN.md, "The
   Dossier Rule Set"): a raised card whose finding-red mark sits above the
   title. The mark is decoration - problem/evidence/action language, never
   a severity; the severity word sits in the card's own meta row. Print has
   no motion: the mark is designed from its finished frame. */
.cards { display: flex; flex-direction: column; gap: var(--space-4); }
.card {
  background: var(--bg);
  border: 1px solid var(--divider);
  border-radius: var(--radius-sm);
  padding: var(--space-4);
}
.card h3::before {
  content: '';
  display: block;
  width: 18px;
  height: 3px;
  border-radius: 2px;
  background: var(--mark-finding);
  margin-bottom: var(--space-2);
}
.card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-4);
  color: var(--muted);
  font-size: 0.85rem;
  margin-top: var(--space-2);
}

/* Category tag in the site's dossier-stamp idiom: soft sky tint, strong
   sky text (site --accent-soft / --accent-strong). */
.tag {
  display: inline-flex;
  align-items: center;
  background: var(--accent-soft);
  color: var(--accent-strong);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
}

.fineprint { color: var(--muted); font-size: 0.85rem; }

/* The article-14 disclosure section reads as fine print, not as a feature
   panel: it never receives card chrome (see section:not(.disclosure)
   above), the section spacing above does the separating. */
.disclosure {
  margin: 0 0 var(--space-6);
}

/* Footer links get real padding so the opt-out link is a comfortable tap
   target on a phone (WCAG 2.5.8 comfort, not just the 24px floor). */
.actions { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.actions a {
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--divider);
  border-radius: var(--radius-sm);
}

/* The reply call to action in the site's primary-button register: the
   near-light ink fill with ground-coloured label, 600, uppercase at the
   site's 0.14em nameplate tracking (DESIGN.md, Site buttons). */
.cta {
  display: inline-block;
  background: var(--text);
  color: var(--bg);
  font-weight: 600;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  text-decoration: none;
  border-radius: 3px;
  padding: var(--space-4) var(--space-6);
}
.cta:focus-visible { outline: 2px solid var(--text); outline-offset: 3px; }

/* The operator PDF prints through this block: the dark ground inverts to
   the paid report's print ground, and the severity tiles swap to the same
   print-safe pairs paged.css derives for #f7f7f5, all measured at 4.5:1
   or better. The scheme declaration flips with it so UA chrome (page
   margins, scrollbars in the print preview) matches the light ground. */
@media print {
  :root {
    color-scheme: light;
    --bg: #f7f7f5;
    --surface: #ffffff;
    --text: #161826;
    --muted: #595d6c;
    --faint: #595d6c;
    --accent: #423a6a;
    --accent-strong: #423a6a;
    --accent-soft: rgba(66, 58, 106, 0.12);
    --divider: rgba(22, 24, 38, 0.2);
    --mark-finding: #a52a37;
    --sev-critical: #a52a37; --sev-critical-bg: #ffffff;
    --sev-serious: #8a5a1e;  --sev-serious-bg: #ffffff;
    --sev-moderate: #6e6a1f; --sev-moderate-bg: #ffffff;
    --sev-minor: #595d6c;    --sev-minor-bg: #ffffff;
  }
  /* The light print wash applies on the element that paints the cover
     gradient (body), not on .cover, or the printed page keeps the dark
     screen glow under print ink. */
  body {
    padding: 0;
    --cover-glow: #dfe9f2;
    --cover-ground: #eef3f8;
  }
  main { max-width: none; }
  .cover {
    min-height: 268mm;
  }
  section:not(.disclosure) { border-color: var(--divider); }
  .card { background: var(--surface); }
  .cta { background: var(--accent); color: #ffffff; letter-spacing: 0.02em; text-transform: none; }
}

@page { size: A4; margin: 14mm; }
`.trim();
